package org.jfree.data.category;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.ResourceBundle;
import org.jfree.data.DataUtilities;
import org.jfree.data.UnknownKeyException;
import org.jfree.data.general.AbstractSeriesDataset;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class DefaultIntervalCategoryDataset_setCategoryKeys_TriageGen1Test {

    @Test
    public void testSetCategoryKeysNullArgument() {
        // Constructor with valid arguments to initialize startData
        Comparable[] seriesKeys = {"Series1"};
        Comparable[] categoryKeys = {"Cat1", "Cat2"};
        Number[][] starts = {{1.0, 2.0}};
        Number[][] ends = {{1.5, 2.5}};
        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        try {
            dataset.setCategoryKeys(null);
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'categoryKeys' argument.", e.getMessage());
        }
    }

    @Test
    public void testSetCategoryKeysLengthMismatch() {
        Comparable[] seriesKeys = {"Series1"};
        Comparable[] categoryKeys = {"Cat1"};
        Number[][] starts = {{1.0, 2.0}}; // length is 2
        Number[][] ends = {{1.5, 2.5}};
        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        try {
            // Providing 2 keys instead of 1 (based on constructor usage, 
            // but the logic checks against startData[0].length which is 2)
            // Let's provide 1 key to trigger mismatch if startData[0] is 2
            dataset.setCategoryKeys(new Comparable[]{"OnlyOne"});
        } catch (IllegalArgumentException e) {
            assertEquals("The number of categories does not match the data.", e.getMessage());
        }
    }

    @Test
    public void testSetCategoryKeysWithNullElement() {
        Comparable[] seriesKeys = {"Series1"};
        Comparable[] categoryKeys = {"Cat1", "Cat2"};
        Number[][] starts = {{1.0, 2.0}};
        Number[][] ends = {{1.5, 2.5}};
        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        try {
            dataset.setCategoryKeys(new Comparable[]{"Cat1", null});
        } catch (IllegalArgumentException e) {
            assertEquals("DefaultIntervalCategoryDataset.setCategoryKeys(): null category not permitted.", e.getMessage());
        }
    }

    @Test
    public void testSetCategoryKeysSuccess() {
        Comparable[] seriesKeys = {"Series1"};
        Comparable[] categoryKeys = {"Cat1", "Cat2"};
        Number[][] starts = {{1.0, 2.0}};
        Number[][] ends = {{1.5, 2.5}};
        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        Comparable[] newCategoryKeys = {"NewCat1", "NewCat2"};
        dataset.setCategoryKeys(newCategoryKeys);

        // Verify the keys were updated via getColumnKey or getColumnKeys
        assertEquals(2, dataset.getColumnCount());
        assertEquals("NewCat1", dataset.getColumnKey(0));
        assertEquals("NewCat2", dataset.getColumnKey(1));
    }
}
